BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "MAGIE" (
	"id_magie"	INTEGER NOT NULL,
	"nom_magie"	TEXT NOT NULL,
	"type_magie"	TEXT NOT NULL,
	"descr_magie"	TEXT NOT NULL,
	"cout_magie"	INTEGER NOT NULL,
	"niveau_magie"	INTEGER,
	PRIMARY KEY("id_magie" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "APTITUDES" (
	"id_aptitude"	INTEGER NOT NULL,
	"nom_aptitude"	TEXT NOT NULL,
	"type_aptitude"	TEXT NOT NULL,
	"descr_aptitude"	TEXT NOT NULL,
	"cout_aptitude"	INTEGER NOT NULL,
	"niveau_aptitude"	INTEGER NOT NULL,
	PRIMARY KEY("id_aptitude" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "POINTS_CARACTERISTIQUES" (
	"id_points_caracteristiques"	INTEGER NOT NULL,
	"nb_points_caracteristiques"	INTEGER NOT NULL,
	"niveau_personnage"	INTEGER,
	PRIMARY KEY("id_points_caracteristiques" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "BOURSE_PERSONNAGE" (
	"id_bourse_personnage"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	"piece_or"	INTEGER,
	"piece_argent"	INTEGER,
	"piece_cuivre"	INTEGER,
	PRIMARY KEY("id_bourse_personnage" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "COMPETENCE_SOCIAL_PERSONNAGE" (
	"id_competence_social"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	"baratinage"	INTEGER NOT NULL,
	"charme"	INTEGER NOT NULL,
	"comedie"	INTEGER NOT NULL,
	"diplomatie"	INTEGER NOT NULL,
	"dressage"	INTEGER NOT NULL,
	"intimidation"	INTEGER NOT NULL,
	"marchandage"	INTEGER NOT NULL,
	"prestance"	INTEGER NOT NULL,
	"provocation"	INTEGER NOT NULL,
	PRIMARY KEY("id_competence_social"),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage")
);
CREATE TABLE IF NOT EXISTS "ATTRIBUTS" (
	"id_attribut"	INTEGER NOT NULL,
	"nom_attribut"	TEXT NOT NULL,
	"description_attribut"	TEXT NOT NULL,
	"type_attribut"	TEXT NOT NULL,
	"note_attribut"	TEXT NOT NULL,
	PRIMARY KEY("id_attribut")
);
CREATE TABLE IF NOT EXISTS "POINTS_CARACTERISTIQUES_PERSONNAGE" (
	"id_points_caracteristiques_personnage"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	"nombre_physique"	INTEGER NOT NULL,
	"nombre_mental"	INTEGER NOT NULL,
	"nombre_social"	INTEGER NOT NULL,
	PRIMARY KEY("id_points_caracteristiques_personnage"),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage")
);
CREATE TABLE IF NOT EXISTS "POINTS_PV_ENERGIE_PERSONNAGE" (
	"id_points_pv_energie_personnage"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	"nombre_points_energie"	INTEGER NOT NULL,
	"nombre_points_pv"	INTEGER NOT NULL,
	PRIMARY KEY("id_points_pv_energie_personnage"),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage")
);
CREATE TABLE IF NOT EXISTS "INVENTAIRE_ARMES_PERSONNAGES" (
	"id_armes_personnages"	INTEGER NOT NULL,
	"id_arme"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	"quantite"	INTEGER NOT NULL,
	PRIMARY KEY("id_armes_personnages" AUTOINCREMENT),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage"),
	FOREIGN KEY("id_arme") REFERENCES "ARMES"("id_armes")
);
CREATE TABLE IF NOT EXISTS "ARMES" (
	"id_armes"	INTEGER NOT NULL,
	"type_arme"	TEXT NOT NULL,
	"nom_arme"	TEXT NOT NULL,
	"poids_arme"	REAL NOT NULL,
	"allonge_arme"	TEXT,
	"main_arme"	TEXT,
	"type_degats_arme"	TEXT NOT NULL,
	"degats_arme"	TEXT NOT NULL,
	"valeur_arme"	INTEGER NOT NULL,
	"description_arme"	TEXT,
	"special_arme"	TEXT,
	PRIMARY KEY("id_armes")
);
CREATE TABLE IF NOT EXISTS "ARMURES" (
	"id_armure"	INTEGER NOT NULL,
	"type_armure"	TEXT NOT NULL,
	"nom_armure"	TEXT NOT NULL,
	"poids_armure"	REAL NOT NULL,
	"valeur_armure"	INTEGER NOT NULL,
	"protection_armure"	TEXT NOT NULL,
	"bonus_armure"	TEXT,
	"description_armure"	TEXT,
	"special_armure"	TEXT,
	PRIMARY KEY("id_armure" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "OBJETS" (
	"id_objets"	INTEGER NOT NULL,
	"nom_objet"	TEXT NOT NULL,
	"poids_objet"	REAL NOT NULL,
	"valeur_objet"	INTEGER NOT NULL,
	"description_objet"	TEXT,
	"type_objet"	TEXT,
	"consommable_objet"	TEXT,
	"special_objet"	TEXT,
	PRIMARY KEY("id_objets" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "MAGIE_PERSONNAGE" (
	"id_magie_personnage"	INTEGER NOT NULL,
	"id_magie"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	PRIMARY KEY("id_magie_personnage"),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage"),
	FOREIGN KEY("id_magie") REFERENCES "MAGIE"("id_magie")
);
CREATE TABLE IF NOT EXISTS "APTITUDES_PERSONNAGE" (
	"id_aptitudes_personnage"	INTEGER NOT NULL,
	"id_aptitude"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	PRIMARY KEY("id_aptitudes_personnage"),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage"),
	FOREIGN KEY("id_aptitude") REFERENCES "APTITUDES"("id_aptitude")
);
CREATE TABLE IF NOT EXISTS "COMPETENCE_PHYSIQUE_PERSONNAGE" (
	"id_competence_physique"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	"agilite"	INTEGER NOT NULL,
	"artisanat"	INTEGER NOT NULL,
	"crochetage"	INTEGER NOT NULL,
	"discretion"	INTEGER NOT NULL,
	"equilibre"	INTEGER NOT NULL,
	"escalade"	INTEGER NOT NULL,
	"escamotage"	INTEGER NOT NULL,
	"force"	INTEGER NOT NULL,
	"fouille"	INTEGER NOT NULL,
	"natation"	INTEGER NOT NULL,
	"reflexes"	INTEGER NOT NULL,
	"vigueur"	INTEGER NOT NULL,
	PRIMARY KEY("id_competence_physique"),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage")
);
CREATE TABLE IF NOT EXISTS "COMPETENCE_MENTAL_PERSONNAGE" (
	"id_competence_mental"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	"concentration"	INTEGER NOT NULL,
	"connaissance_geographiques"	INTEGER NOT NULL,
	"connaissance_historiques"	INTEGER NOT NULL,
	"connaissance_magiques"	INTEGER NOT NULL,
	"connaissance_natures"	INTEGER NOT NULL,
	"connaissance_religieuses"	INTEGER NOT NULL,
	"decryptage"	INTEGER NOT NULL,
	"esprit"	INTEGER NOT NULL,
	"explosifs"	INTEGER NOT NULL,
	"mecanique"	INTEGER NOT NULL,
	"medecine"	INTEGER NOT NULL,
	"memoire"	INTEGER NOT NULL,
	"perception"	INTEGER NOT NULL,
	"volonte"	INTEGER NOT NULL,
	PRIMARY KEY("id_competence_mental"),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage")
);
CREATE TABLE IF NOT EXISTS "INVENTAIRE_ARMURES_PERSONNAGES" (
	"id_inventaire_armures_personnages"	INTEGER NOT NULL,
	"id_armure"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	"quantite"	INTEGER NOT NULL,
	PRIMARY KEY("id_inventaire_armures_personnages" AUTOINCREMENT),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage"),
	FOREIGN KEY("id_armure") REFERENCES "ARMURES"("id_armure")
);
CREATE TABLE IF NOT EXISTS "INVENTAIRE_OBJETS_PERSONNAGES" (
	"id_inventaire_objets_personnages"	INTEGER NOT NULL,
	"id_objets"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	"quantite"	INTEGER NOT NULL,
	PRIMARY KEY("id_inventaire_objets_personnages" AUTOINCREMENT),
	FOREIGN KEY("id_objets") REFERENCES "OBJETS"("id_objets"),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage")
);
CREATE TABLE IF NOT EXISTS "POINTS_VIE_ENERGIE" (
	"id_points_repartir"	INTEGER NOT NULL,
	"nb_point_personnage"	INTEGER NOT NULL,
	"niveau_personnage"	INTEGER,
	PRIMARY KEY("id_points_repartir" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "ATTRIBUTS_PERSONNAGE" (
	"id_attribut_personnage"	INTEGER NOT NULL,
	"id_attribut"	INTEGER NOT NULL,
	"id_personnage"	INTEGER NOT NULL,
	"specifications"	TEXT,
	PRIMARY KEY("id_attribut_personnage"),
	FOREIGN KEY("id_attribut") REFERENCES "ATTRIBUTS"("id_attribut"),
	FOREIGN KEY("id_personnage") REFERENCES "PERSONNAGE"("id_personnage")
);
CREATE TABLE IF NOT EXISTS "PERSONNAGE" (
	"id_personnage"	INTEGER NOT NULL,
	"prenom_personnage"	TEXT NOT NULL,
	"nom_personnage"	TEXT NOT NULL,
	"race_personnage"	TEXT NOT NULL,
	"niveau_personnage"	INTEGER NOT NULL,
	"sexe_personnage"	TEXT NOT NULL,
	"experience_personnage"	INTEGER,
	"courbe_progression_personnage"	TEXT,
	"niveau_suivant_personnage"	INTEGER,
	"langues_personnage"	TEXT NOT NULL,
	"avatar_personnage"	TEXT,
	"histoire_personnage"	TEXT,
	"charge_portee_personnage"	REAL,
	"charge_totale_personnage"	REAL,
	PRIMARY KEY("id_personnage" AUTOINCREMENT)
);
CREATE TABLE IF NOT EXISTS "REF_TYPE_DEGATS" (
	"id_type_degats"	INTEGER,
	"code"	TEXT NOT NULL UNIQUE,
	"libelle"	TEXT NOT NULL,
	PRIMARY KEY("id_type_degats")
);
CREATE TABLE IF NOT EXISTS "REF_QUALITE" (
	"qualite"	INTEGER,
	"mult_cout"	REAL NOT NULL,
	PRIMARY KEY("qualite")
);
CREATE TABLE IF NOT EXISTS "MATERIAUX_COUTS" (
	"id_materiau"	INTEGER NOT NULL,
	"base_valeur"	INTEGER NOT NULL,
	"rarete"	INTEGER NOT NULL,
	UNIQUE("id_materiau"),
	FOREIGN KEY("id_materiau") REFERENCES "MATERIAUX"("id_materiau") ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "MATERIAUX_EFFETS_OLD" (
	"id_materiau"	INTEGER NOT NULL,
	"id_type_degats"	INTEGER NOT NULL,
	"qualite"	INTEGER NOT NULL,
	"valeur_effect"	INTEGER NOT NULL,
	PRIMARY KEY("id_materiau","id_type_degats","qualite"),
	FOREIGN KEY("qualite") REFERENCES "REF_QUALITE"("qualite"),
	FOREIGN KEY("id_type_degats") REFERENCES "REF_TYPE_DEGATS"("id_type_degats"),
	FOREIGN KEY("id_materiau") REFERENCES "MATERIAUX"("id_materiau") ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "REF_EFFETS" (
	"id_effet"	INTEGER,
	"code"	TEXT NOT NULL UNIQUE,
	"libelle"	TEXT NOT NULL,
	"categorie"	TEXT NOT NULL,
	"unite"	TEXT NOT NULL CHECK("unite" IN ('pct', 'flat')),
	PRIMARY KEY("id_effet")
);
CREATE TABLE IF NOT EXISTS "MATERIAUX_EFFETS" (
	"id_materiau"	INTEGER NOT NULL,
	"id_effet"	INTEGER NOT NULL,
	"qualite"	INTEGER NOT NULL,
	"valeur"	REAL NOT NULL,
	PRIMARY KEY("id_materiau","id_effet","qualite"),
	FOREIGN KEY("id_effet") REFERENCES "REF_EFFETS"("id_effet") ON DELETE CASCADE,
	FOREIGN KEY("id_materiau") REFERENCES "MATERIAUX"("id_materiau") ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "MATERIAUX" (
	"id_materiau"	INTEGER,
	"nom_materiau"	TEXT NOT NULL UNIQUE,
	"categorie"	TEXT NOT NULL,
	"realisme"	TEXT NOT NULL,
	"description"	TEXT,
	PRIMARY KEY("id_materiau")
);
CREATE TABLE IF NOT EXISTS "MATERIAUX_VALEUR" (
	"id_materiau"	INTEGER NOT NULL,
	"qualite"	INTEGER NOT NULL,
	"valeur"	REAL NOT NULL,
	PRIMARY KEY("id_materiau","qualite"),
	FOREIGN KEY("id_materiau") REFERENCES "MATERIAUX"("id_materiau") ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "MATERIAUX_POIDS" (
	"id_materiau"	INTEGER NOT NULL,
	"qualite"	INTEGER NOT NULL,
	"poids"	REAL NOT NULL CHECK("poids" >= 0),
	PRIMARY KEY("id_materiau","qualite"),
	FOREIGN KEY("id_materiau") REFERENCES "MATERIAUX"("id_materiau") ON DELETE CASCADE
);
INSERT INTO "MAGIE" VALUES (0,'','','',0,NULL);
INSERT INTO "MAGIE" VALUES (1,'Manipulation de l''eau','Aquatique','Au niveau 1, vous pouvez générer une faible quantité d''eau avec ce sortilège, vous pouvez également manipuler de l''eau pure, pas de l''eau salé. Toute action spécifique est à la libre appréciation du maître du jeu.',2,1);
INSERT INTO "MAGIE" VALUES (2,'Manipulation des flammes','Ignis','Au niveau 1, vous pouvez créer des flammes faibles, mais capable d''embrasser l''ennemi malgré tout, vous avez également un contrôle sur les petites flammes telles que les torches et vous pouvez les éteindres. Toute action spécifique est à la libre appréciation du maître du jeu.',2,1);
INSERT INTO "MAGIE" VALUES (3,'Manipulation des éléments célestes','Céleste','Au niveau 1, vous pouvez générer des formes à partir des éléments célestes (foudre, vent) ou faire appel à ces derniers s''ils sont présents dans l''environnement. Toute action spécifique est à la libre appréciation du maître du jeu.',2,1);
INSERT INTO "MAGIE" VALUES (4,'Manipulation de la terre','Terrestre','Au niveau 1, vous pouvez manipuler la terre et créer des formes à partir de la terre. Toute action spécifique est laissée à la libre appréciation du MJ.',2,1);
INSERT INTO "MAGIE" VALUES (5,'Communication avec la faune','Nature','En lançant cette incantation, vous serez capable de parler avec les animaux. Qu''ils soient vivipare, ovipare, galinacés, mammifères, vous pourrez parler avec les tous les animaux.',3,1);
