INSERT INTO "ATTRIBUTS" VALUES (1,'Alifère','La créature peut voler jusqu''à une certaine altitude','Innée','1. Le nombre de mètres d''altitudes est à fixer avec le MJ');
INSERT INTO "ATTRIBUTS" VALUES (2,'Amphibien','La créature peut respirer sur terre comme sous l''eau','Innée','Aucune');
INSERT INTO "ATTRIBUTS" VALUES (3,'Armure naturelle','La créature possède une peau épaisse qui lui permet d''encaisser un pourcentage des dégâts reçus','Évolution','1. Le pourcentage de dégâts encaisser est à fixer avec le MJ');
INSERT INTO "ATTRIBUTS" VALUES (4,'Avantage du terrain','Sur un ou plusieurs terrains, la créature n''a pas de malus','Évolution','1. Le ou les terrains sont à fixer avec le MJ');
INSERT INTO "ATTRIBUTS" VALUES (5,'Bras fragiles','La créature a des bras fragiles et ne peut pas porter beaucoup de poids','Malus','1. Le poids total que peut transporter la créature est divisée par trois.');
INSERT INTO "ATTRIBUTS" VALUES (6,'Canaliseur','La créature posséde un pourcentage supplémentaire de ses points d''énergie basé sur le total','Innée','1. Le pourcentage est à fixer avec le MJ');
INSERT INTO "ATTRIBUTS" VALUES (7,'Célérité	','La créature a le premier tour d''initiative en combat','Évolution','1. Si plusieurs créatures ont cet attribut, l''avantage revient à celui qui fait le meilleur jet d''Agilité (plus petit score).
1.1. Si le score est le même, l''avantage revient au PJ');
INSERT INTO "ATTRIBUTS" VALUES (8,'Corps artificiels','La créature a été créée artificiellement et n''a donc pas besoin de respirer pour vivre.','Innée','Aucun');
INSERT INTO "ATTRIBUTS" VALUES (9,'Dégagement','Impossible pour la créature d''être encerclé','Évolution','Aucune');
INSERT INTO "ATTRIBUTS" VALUES (10,'Frigifugé','La créature peut survivre à de basses température jusqu''à un certain degré celsius','Innée','1. La température sera à fixer en celsius avec le MJ');
INSERT INTO "ATTRIBUTS" VALUES (11,'Gigantisme','La créature est tellement grande que ses adversaires ont un bonus pour le toucher','Malus','1. Le bonus est à fixer avec le MJ');
INSERT INTO "ATTRIBUTS" VALUES (12,'Grimpeur','La créature peut grimper sur des surfaces solides (comme les murs) sans soucis','Innée','Aucune');
INSERT INTO "ATTRIBUTS" VALUES (13,'Coagulation','Le sang de la créature lui permet d''arrêter le saignement au bout de 1d4 tour(s)','Innée','Aucune');
INSERT INTO "ATTRIBUTS" VALUES (14,'Gros dormeur','La créature peut lancer un dé supplémentaire pour regagner des points de vie après un repos.','Évolution','Aucune');
INSERT INTO "ATTRIBUTS" VALUES (15,'Hyperesthésie','La créature possède une résistance à la paralysie','Innée','Aucune');
INSERT INTO "ATTRIBUTS" VALUES (16,'Ignifugé','Le créature peut survivre à des températures élevées','Innée','1. Le degré exact est à fixer avec le MJ');
INSERT INTO "ATTRIBUTS" VALUES (17,'Magicien','La créature peut utiliser la magie','Innée','1. Les magies maîtrisées sont à fixer avec le MJ');
INSERT INTO "ATTRIBUTS" VALUES (18,'Porteur de charges lourdes','La créature peut porter un pourcentage supplémentaire d''objet par rapport à sa charge maximale','Évolution','1. Le pourcentage est à fixer avec le MJ');
INSERT INTO "ATTRIBUTS" VALUES (19,'Force surhumaine','La créature a une force supérieure à la normale','Innée','1. La créature peut lancer un dé supplémentaire pour les dégâts
2. Elle peut porter plus de poids');
INSERT INTO "INVENTAIRE_ARMES_PERSONNAGES" VALUES (1,1,2,3);
INSERT INTO "ARMES" VALUES (1,'Épée','Scramasax',0.55,'45 cm','Une','Tranchant','1d6+1',120,'Cette arme a un tranchant est pratique lors des explorations où la flore est luxuriante pour se frayer un chemin en découpant tout ce qui bouge. Au combat, elle est souvent utilisée par des hommes qui n’ont pas eu les moyens de s’acheter de meilleure arme, son prix reste abordable pour un aventurier débutant, mais le paysan du coin ne pourra pas se payer le luxe de se l’offrir.','Aucun');
INSERT INTO "ARMES" VALUES (2,'Épée','Épée courte',0.35,'65 cm','Une','Tranchant','1d6',108,'L’épée la plus banale que tout bon guerrier possède, elle a une bonne allonge et ne coûte pas trop cher. Il n’y a que les aventuriers débutants qui se baladent avec ce genre d’épée, car elle n’a pas d’apport particulier en combat, ça reste surtout une arme de secours au cas où on venait de perdre son arme favorite. ','Aucun');
INSERT INTO "ARMES" VALUES (3,'Épée','Épée lourde',1.5,'1 m','Deux','Tranchant','2d8+8',275,'Cette épée-là est faite spécialement pour faire de gros dégâts, réservée aux guerriers qui n’ont pas froid aux yeux, elle est tellement lourde qu’il faut la tenir à deux mains. Son maniement demande un petit temps d’adaptation, mais elle permet de causer de gros dégâts aux ennemis si jamais vous parvenez à lui asséner un violent coup avec cette arme.','Aucun');
INSERT INTO "ARMES" VALUES (4,'Épée','Glaive',0.6,'60 cm','Une','Tranchant','1d6+3',124,'Le glaive est un excellent compromis pour ceux qui ne savent pas quelle arme prendre au corps à corps, elle est plus lourde qu’une épée courte lambda, mais elle permet également une bien meilleure offensive. Elle est généralement placée à la ceinture comme arme secondaire au cas où le guerrier venait à perdre son arme principale.','Aucun');
INSERT INTO "ARMES" VALUES (5,'Épée','Latte',0.5,'90 cm','Une','Tranchant','1d8+1',185,'Le latte (à ne pas confondre avec la latte pour le sommier) est un type de sabre dont la lame est droite et non courbée. Généralement utilisée par les équipages maritimes, si jamais ils venaient à rencontrer un problème en mer, comme un abordage de pirates, ces sabres leur permettrait de se battre efficacement avec une seule main tout en faisant des dommages conséquents à l’ennemi.','Aucun');
INSERT INTO "ARMES" VALUES (6,'Épée','Sabre courbé',0.45,'90 cm','Une','Tranchant','1d8',170,'Le sabre courbé est une arme généralement détenue par les habitants du désert car, grâce à sa flexibilité et à son tranchant, on peut mieux faire face aux dangers présents dans cet endroit. Le métal étant répartit différemment, ce sabre est légèrement moins lourd que son cousin le latte. Il fait également moins mal, mais pour une arme à une main c’est tout à fait correct.','Aucun');
INSERT INTO "ARMES" VALUES (7,'Épée','Épée en bois',0.25,'50 cm','Une','Contondant','1',65,'L’épée en bois est principalement une arme d’entraînement, il est extrêmement rare que quelqu’un parvienne à défaire un ennemi avec ce genre d’épée. Si l’artisan a bien effectué son travail, elle ne se brisera pas sous les coups, ou en en donnant à l’ennemi. Du moins, tant que son utilisation reste telle que l’épée a été conçu à la base.','Aucun');
INSERT INTO "ARMES" VALUES (8,'Épée','Épée bâtarde',1.25,'1,5 m','Une/Deux','Tranchant','2/1d8+3',355,'L’épée bâtarde est un excellent compromis pour ceux qui hésitent entre faire des dégâts fracassants ou rester sur la défensive, ou pour ceux, qui en plein combat, voudrait changer leur mode d’attaque. Sa polyvalence explique son coût supérieure à la normale par rapport à d’autres épées. ','1. Pour les personnages possédant l''attribut Force surhumaine ou Force de géants, ils n''ont pas besoin de tenir l''arme à deux mains pour exploiter sa pleine puissance.');
INSERT INTO "ARMES" VALUES (9,'Lance','Contus',10.0,'4 m','Deux','Perforant','2d12+10',1166,'Cette lance est prévue spécialement pour la cavalerie, elle est tellement lourde qu’il est quasiment impossible de s’en servir en dehors des joutes de chevaleries. Presque impossible, car une personne ou une créature avec une force supérieure à la moyenne pourra s’en servir en dehors de son utilisation de base comme si c’était une lance normale.','1. Il est impossible de se servir de cette arme sans être sur une monture !
1.1. À l’exception des personnages avec l’attribut Force surhumaine ou Force de géant qui peuvent s’en servir sans être sur une monture.');
INSERT INTO "ARMES" VALUES (10,'Lance','Javelot',1.0,'3 m','Une','Perforant ','1d6+2',472,'Le javelot est une arme de jet, c’est-à-dire qu’il a été conçu pour être jeté sur l’adversaire et non utilisé comme une arme au corps-à-corps. Bien que cet usage soit possible, le mieux que vous puissiez faire avec un javelot est vous tenir à bonne distance de l’ennemi, puis le lancer sur son adversaire, bien qu’évidemment, ça nécessite de retourner le chercher…','1. Si l’arme est lancée pour atteindre une cible à distance, les dégâts si la cible est touchée seront calculés ainsi : 
1.1. (dé(s) PJ  * 2 )d12+4
2. La distance maximale d’où peut être tirée l’arme est la suivante :
2.1. 9 m + (Force PJ/ 3)
');
INSERT INTO "ARMES" VALUES (11,'Lance','Fourche',0.8,'2 m','Une','Perforant','1d4',36,'À la base, la fourche est faite pour manipuler le foin et nourrir les animaux, mais prenez-vous un coup de fourche dans la tête et vous allez voir que ça peut servir en dehors de la ferme. Enfin, elle n’est pas faite pour être utilisée en combat, donc ses dommages restent relatifs.','Aucun');
INSERT INTO "ARMES" VALUES (12,'Lance','Sarisse',4.0,'5 m','Une','Perforant','1d8+2',440,'Le style soigné de cette arme permet de à la Sarisse de s’enfoncer plus facilement dans la chair de ses victimes afin de causer un maximum de dégâts. C’est certainement la lance la plus commune trouvable chez tous les aventuriers, permettant un compromis entre combat à dos de monture, attaque à distance, et combat au corps-à-corps.','Aucun');
INSERT INTO "ARMES" VALUES (13,'Lance','Trident',5.0,'4 m','Une','Perforant','1d8+4',648,'Cette lance est utilisée principalement pour les combats d’arènes, lorsque le champion doit lutter contre les autres gladiateurs ou les bêtes envoyées par le dirigeant du peuple. Bien que légèrement plus courte que sa cousine la Sarisse, cette arme est bien plus efficace au corps-à-corps que cette dernière, ayant été spécialement créée pour ça.','Aucun');
INSERT INTO "ARMES" VALUES (14,'Poignard','Couteau',0.21,'23 cm','Une','Perforant/Tranchant','1d2',16,'Ce couteau de cuisine est bien pratique pour découper la viande et les légumes, cependant, son utilité au combat est beaucoup plus discutable. Non seulement sa lame peut se briser facilement, mais en plus, il ne provoquera pas de dommages importants chez l’ennemi. À utiliser en dernière mesure, si l’on n’a rien d’autre sous la main.','1. La lame peut se briser en donnant un coup à l’ennemi avec.
1.1 Lancer 1d100, si le résultat est entre 96 et 100 (les deux pôles compris) l’arme se brise
1.2 Si en attaquant avec cette arme la personne fait un échec critique, elle se brise automatiquement.');
INSERT INTO "ARMES" VALUES (15,'Poignard','Dague',0.15,'29 cm','Une','Perforant/Tranchant','1d4+2',96,'Chaque guerrier apporte avec lui une dague dans le cas où il perdrait ses autres armes. Très légère, plus affutée qu’un couteau normal, c’est l’arme parfaite en cas de survie si l’on a perdu ses autres armes. En plus, elle est facilement maniable par tout le monde.','Aucun');
INSERT INTO "ARMES" VALUES (16,'Poignard','Faucille de guerre',0.3,'30 cm','Une','Perforant/Tranchant','1d4+4',125,'Dérivée des faucilles permettant de couper le blé dans les champs, cette faucille a été spécialement faites pour le champ de bataille. Déchirant les organes comme du beurre, son style convient mieux aux assassins ou aux personnes ne se battant pas avec des armes de mêlées, qu’aux guerriers qui préfèrent affronter l’ennemi de front.','Aucun');
INSERT INTO "ARMES" VALUES (17,'Poignard','Dague d''assassin',0.2,'35 cm','Une','Perforant/Tranchant','1d6+1',145,'Cette dague a été spécialement conçue il y a longtemps par un grand assassin, son tranchant, plus efficace que celui d’un poignard normal, permet de tuer rapidement, et discrètement sa victime en l’égorgeant. Bien que sa lame soit assez grande pour une dague, on peut facilement dissimuler l’arme. Une arme vraiment parfaite pour les assassins.','1. Lorsqu’elle est cachée, si un personnage fouille la créature qui possède cette arme, elle a un malus de -15% en Perception.');
INSERT INTO "ARMES" VALUES (18,'Hache','Francisque',1.3,'75 cm/4 m au lancer','Une','Tranchant','1d6+3/1d10+2',476,'Cette hache est une des premières de son espèce à pouvoir être jetée. Elle a été spécialement confectionnée pour ça à vrai dire, vous pourrez tirer son plein potentiel uniquement en la lançant sur son adversaire. Au corps-à-corps, elle peut rester un bon compromis, mais son manche en bois pourrait se briser, s’il se prend un coup ennemi, prudence donc.','1. Si l’ennemi frappe la francisque, il y a une chance que le manche se brise sous le coup et qu’elle ne puisse plus être utilisée.
1.1 Si le propriétaire a la francisque en main, et que son adversaire tente de détruire le manche pour le désarmer, il peut tenter un jet de Réflexes pour éviter le coup.
2. La règle précédente ne s’applique pas si la francisque est lancée, elle a été conçue pour résister à ce genre de choc.');
INSERT INTO "ARMES" VALUES (19,'Hache','Hache de bûcheron',2.5,'55 cm','Deux','Tranchant','2d6+4',193,'Forgée pour découper des arbres, c’est tout naturellement qu’elle reste une arme extrêmement efficace sur le terrain. En effet, ni trop difficile à fabriquer, ni trop chère, on retrouve souvent cette arme parmi les berserkers ou les déments qui n’ont pas froid aux yeux et qui se lancent à corps perdu dans le combat sans craindre pour leur vie, car en effet, seule son allonge est un problème.','1. Pour les personnages possédant l''attribut Force surhumaine ou Force de géants, ils n''ont pas besoin de tenir l''arme à deux mains pour exploiter sa pleine puissance.');
INSERT INTO "ARMES" VALUES (20,'Masse','Massue de chêne',0.55,'45 cm','Une','Contondant','1d4+5',210,'Très souvent utilisée par des sauvages ou des petites créatures, elle a l’avantage d’être petite et donc d’être portée facilement à la ceinture. Évidemment, même si son matériau de base est un chêne, son bois a été travaillé pour être suffisamment résistant aux coups que l’arme pourrait recevoir ou donner.','1. S’il vous faite une réussite critique à la tête avec cette arme, l’ennemi est assommé.
1.1. Si l’adversaire a un casque qui protège contre les attaques contondantes, il ne peut pas être assommé.');
INSERT INTO "ARMES" VALUES (21,'Masse','Marteau de forgeron',1.9,'50 cm','Une','Contondant','1d6+2',310,'Ce marteau frappe tous les jours contre le métal dans la forge de son détenteur, c’est grâce à lui que toutes vos armes sont confectionnées. Bien qu’il soit confectionné uniquement pour la fabrication de pièces d’armure ou d’armes, quelqu’un a eu l’idée ingénieuse de s’en servir comme arme, car même s’il n’est pas bien grand, sa tête de métal permet de fracasser des os. ','1. S’il vous faite une réussite critique à la tête avec cette arme, l’ennemi est assommé.
1.1. Si l’adversaire a un casque qui protège contre les attaques contondantes, il ne peut pas être assommé.');
INSERT INTO "ARMES" VALUES (22,'Arme de trait','Arc',1.0,'18 m','Deux','Perforant','2d6+munition',832,'Certainement une des armes les plus prisées par ceux qui ne maîtrisent pas la magie, mais qui aurait malgré tout trop peur d’aller se battre au corps-à-corps. Taillé dans un bois de chêne résistant, renforcé avec des morceaux de métal, l’arc permet de tirer des projectiles depuis de longue distance sans craindre les ennemis, car il est aisé de s’enfuir si le combat ne tournait pas l’avantage de l’archer.','1. Requiert l’attribut Artilleur pour s’en servir sans malus.');
INSERT INTO "ARMES" VALUES (23,'Arme de trait','Arbalète',2.0,'15 m','Deux','Perforant','2d8+munition',951,'Dotée projection mécanique, l’arbalète peut envoyer plus vite, et plus fort un carreau sur sa cible que ne le pourrait un arc. Ce qui cause bien souvent de grands dommages en perforant les défenses ennemies, même les armures les plus robustes voient parfois les carreaux d’arbalètes les transpercer. Seul inconvénient, sa portée est légèrement en deçà de celle de l’arc, et coûte plus cher.','1. Requiert l’attribut Artilleur pour s’en servir sans malus.');
INSERT INTO "ARMES" VALUES (24,'Arme de trait','Fronde',0.03,'9 m','Une','Contondant','1d6+munition',260,'Souvent utilisé par les bergers pour défendre leurs troupeaux des prédateurs comme les loups, la fronde est une arme efficace capable d’être utilisée d’une seule main pour défaire toucher sa cible. Elle a surtout un but dissuasif, car, bien que dans le temps les fantassins ne portaient pas de casque pour protéger leur tête se prenant ainsi les projectifs en pleine face, maintenant, il est très rare de voir les guerriers sans protection au visage rendant cette arme surtout dissuasive.','Aucun');
INSERT INTO "ARMES" VALUES (25,'Chaîne','Fouet',0.13,'2.5 m','Une','Contondant','1d6',269,'Fabriqué à partir du cuir de bêtes, tressés d’une façon particulière en ajoutant des morceaux de métal entre chaque lanière, cette arme a été conçue pour arracher la chair de ceux qui se prennent des coups avec. Principalement utilisé pour faire avancer les esclaves lorsqu’ils ont un coup de mou, le fouet peut très bien servir dans d’autres situations.','Aucun');
INSERT INTO "ARMES" VALUES (26,'Chaîne','Faucille à chaîne',0.9,'3 m','Une','Tranchant','1d10',395,'Plusieurs chaînes de fer, surmontées par une faucille tranchante comme une lame de rasoir, voilà ce qu’est cette arme. Elle permet aux gens les plus adroits d’attaquer bonne distance, et souvent par surprise, ne craignez pas que la tête se retrouve coincée dans le corps de ses victimes, car elle a justement été créée pour en ressortir facilement, armure ou non. ','Aucun');
INSERT INTO "ARMES" VALUES (27,'Bâton','Bâton de chêne',0.25,'60 cm','Une','Contondant','1',23,'Cette « arme » a été créée uniquement pour que certains se fassent passer pour des mages, elle ne fait pratiquement aucuns dégâts, elle peut se briser facilement. Elle peut servir à soutenir lors de grandes marches en pleine nature remarque.','1. Au combat, il peut se briser s’il met ou s’il reçoit un coup.
1.1. Lancer 1d100 à chaque coup porté ou reçu avec cette arme, si le résultat est entre 80 et 100 (les deux pôles compris), l’arme est brisée en deux.');
INSERT INTO "ARMES" VALUES (28,'Bâton','Sceptre des fées',0.5,'70 cm','Une','Contondant','1',2078,'On dit de ce bâton qu’il a été détenu il y a longtemps par un prince ou une princesse fée, ce qui en fait sa rareté. Il est sensible à tout type de magie, ce qui en fait le bâton parfait si vous êtes un adepte de plusieurs formes de magie. Il a été taillé dans un type de bois spécial, puis enchanté pour être quasiment indestructible, ainsi, il est impossible avec des moyens conventionnels de briser cette arme.','1. Au combat, il retire automatiquement un point d’énergie à utiliser dans tous types de magie lorsque l’utilisateur lance n’importe quel type de sortilège.');
INSERT INTO "ARMES" VALUES (29,'Bâton','Canne Aquatique',0.45,'75 cm','Une','Contondant','1',220,'Fabriqué dans du bois de boulot, cette canne a été enchantée par les nymphes qui ont un attrait particulièrement pour l’élément de l’eau. Ainsi, son détenteur verra son énergie à consommer pour lancer des sorts liés à l’eau, réduite.','1. Au combat, elle retire automatiquement un point d’énergie à utiliser dans la magie aquatique.');
INSERT INTO "ARMES" VALUES (30,'Bâton','Baguette de feu',0.35,'35 cm','Une','Perforant','1',203,'Taillée à partir du bois d’un arbre de lave, cette baguette a été créée par une sorcière il y a bien longtemps afin de faciliter l’usage de ses sorts de feu. Elle a ensuite été popularisée quand ses comparses ont vu son utilisation.','1. Au combat, elle retire automatiquement un point d’énergie à utiliser dans la magie ignis.');
INSERT INTO "ARMES" VALUES (31,'Bâton','Bâton céleste',0.25,'60 cm','Une','Contondant','1',256,'Cette fois-ci, ce « bâton » n’est pas fabriqué dans un bois quelconque, mais dans de l’acier mélangé à un alliage de bronze. La tête du bâton à quant à lui, était fait avec un alliage de cuivre et d’argent et le réceptacle tenant la pierre élémentaire est fait avec des feuilles d’or. Plusieurs métaux ont donc été mélangés pour ce bâton, mais c’est sûrement pour souligner la finesse de son élément.','1. Au combat, il retire automatiquement un point d’énergie à utiliser dans la magie céleste.');
INSERT INTO "ARMES" VALUES (32,'Bâton','Sceptre terrestre',0.55,'70 cm','Une','Contondant','1',223,'Des mines, on a extrait énormément de rocher pour créer le cœur qui compose ce sceptre magique. Surmonté d’un topaze, le sceptre est fabriqué a été fabriqué dans du cuivre pour mieux conduire ses pouvoirs magiques liés à la terre.','1. Au combat, il retire automatiquement un point d’énergie à utiliser dans la magie terrestre.');
INSERT INTO "ARMES" VALUES (33,'Bâton','Bâton des sylves',0.4,'65 cm','Une','Contondant','1',296,'Bien que l’on pourrait croire que ça ne soit qu’un simple bâton de bois, il n’en est rien, les magiciens pourront le dire : ce bois a été enchanté par les sylves. Petits esprits farouches de la nature, ils font quelque fois cadeau de cet artefact aux personnes qu’ils apprécient, généralement les druides ou les personnes très proches de la nature. Ça n’empêche pas d’en trouver sur les lieux où l’influence magique est fort présente.','1. Au combat, il retire automatiquement un point d’énergie à utiliser dans la magie de la nature.');
INSERT INTO "ARMES" VALUES (34,'Bâton','Canne de lumière',0.65,'65 cm','Une','Contondant','1',353,'Extrait d’un métal magique d’une extrême pureté, puis frappé et forgé par un forgeron aguerri connaissant ce genre de métaux et enfin, purifiée par diverses prières de saints, c’est ainsi qu’est faite cette canne. Du fait de sa création, elle permet de rentrer plus facilement en communication avec les pouvoirs du Divin et d’accomplir la volonté de sa déité avec.','1. Au combat, elle retire automatiquement un point d’énergie à utiliser dans la magie divine.');
INSERT INTO "ARMES" VALUES (35,'Bâton','Baguette infernale',0.37,'40 cm','Une','Perforant','1',218,'Créée à partir d’un métal qu’on dit venir d’un plan inférieur, rempli d’entité aux intentions néfastes, cette baguette est forgée par très peu d’adeptes de la magie très proches de ce qu’on pourrait nommer ténèbres. Des marques et des sceaux de magie noire sont gravée un peu partout sur la baguette, facilitant la communication avec le Mauvais.','1. Au combat, elle retire automatiquement un point d’énergie à utiliser dans la magie corrompue.');
INSERT INTO "ARMES" VALUES (36,'Bâton','Sceptre de neutralité',0.7,'60 cm','Une','Contondant','1',253,'Il fallait bien qu’un mage, spécialisé dans les tours de passe-passe, se décide un jour à créer un artefact magique pour lui faciliter la tâche lors de ses expérimentations avec la magie qui n’utilise aucun élément et ne communiquant ni avec le divin, ni le malin, ni la nature. C’est ainsi que vit le jour ce sceptre. Son apparence varie en fonction de l’endroit dans le monde où il est fabriqué.','1. Au combat, il retire automatiquement un point d’énergie à utiliser dans la magie neutre.');
INSERT INTO "ARMES" VALUES (37,'Poignard','Dague de Cardaillite',6.25,'50 cm','Une','Perforant/Tranchant','1d8+2',1047,'Presque aussi longue qu''une épée, il fallait bien ça pour forger une dague en Cardaillite digne de ce nom. Très tranchante, ce sont des dagues redoutables qu''il vaut mieux espérer ne pas croiser lors de combats. Elle a un aspect doré dû au minerai dans lequel elle a été forgé.','Aucun');
INSERT INTO "ARMURES" VALUES (1,'Casque','Spangenhelm',4.0,476,'Tranchant, Contondant, Perforant','3','Le Spangenhelm est un casque caractérisé par sa structure en forme de bol, généralement en fer, et sa conception composée de plusieurs plaques métalliques (appelées "spangen") rivetées ensemble. Il offre une bonne protection de la tête et présente souvent des ornements tels que des protège-joues et une crête centrale.','Aucun');
INSERT INTO "ARMURES" VALUES (2,'Casque','Coiffe de mailles',2.5,284,'Tranchant, Perforant','4','Elle est fabriquée en interconnectant de petites pièces de métal, appelées "mailles", pour former une structure souple et résistante. La coiffe de mailles couvre entièrement la tête, y compris le cou et parfois les épaules. Elle offre une excellente protection contre les coups de lame et les projectiles.','Aucun');
INSERT INTO "ARMURES" VALUES (3,'Casque','Morion',1.7,256,'Perforant, Contondant','4','Il est caractérisé par sa forme distincte avec une calotte bombée et des bords relevés. Le morion est généralement fabriqué en acier et présente souvent des ornements décoratifs tels que des plumes, des glands ou des ciselures. Il couvre principalement la partie supérieure de la tête et offre une protection limitée pour le visage.','Aucun');
INSERT INTO "ARMURES" VALUES (4,'Casque','Cervelière',1.6,221,'Perforant','3','Elle est caractérisée par sa forme en dôme avec une partie supérieure arrondie et des bords droits ou légèrement évasés. La cervelière est généralement fabriquée en métal, telle que l''acier, et elle couvre principalement le sommet de la tête. Elle offre une bonne protection contre les coups contondants.','Aucun');
INSERT INTO "ARMURES" VALUES (5,'Casque','Chapel de fer',1.9,346,'Tranchant, Contondant, Perforant','2','Elle est caractérisée par sa forme conique avec un sommet pointu et des bords évasés. La chapelle de fer offre une bonne protection pour la tête, le visage et le cou. Elle comporte souvent une visière articulée qui peut être relevée ou abaissée pour protéger le visage.','Aucun');
INSERT INTO "ARMURES" VALUES (6,'Casque','Casque de barbare',1.8,330,'Tranchant, Contondant, Perforant','1','Le casque barbare a une calotte arrondie avec une partie supérieure souvent ornée de motifs ou de crêtes. Il possède généralement des protège-joues qui couvrent les côtés du visage, et parfois une protection nasale pour protéger le nez. Ces casques offrent une protection adéquate pour la tête, le visage et les côtés du visage, tout en permettant une bonne visibilité et une meilleure ventilation que les casques plus couvrants','Aucun');
INSERT INTO "ARMURES" VALUES (7,'Buste','Vêtements',0.2,11,'Rien','0','Il s’agit surtout de ne pas sortir à poil, donc, pour la bienséance, merci de vous procurer ces vêtements. En plus, juste porter une armure ça fait froid.','Aucun');
INSERT INTO "ARMURES" VALUES (8,'Buste','Broigne',20.0,1395,'Tranchant, Perforant','5','Une broigne est un type d''armure défensive utilisée pendant le Moyen Âge. Elle est composée de nombreux anneaux de métal interconnectés, formant une sorte de tissu métallique. La broigne est similaire à la cotte de mailles, mais au lieu de mailles individuelles, elle utilise de petites plaques de métal perforées appelées "broignons" qui sont liées ensemble. La broigne offre une protection contre les coups d''arme tranchante et les projectiles. Elle couvre généralement le torse, le dos et les épaules, parfois avec des manches intégrées pour protéger les bras.','Aucun');
INSERT INTO "ARMURES" VALUES (9,'Buste','Plastron de cataphracte',22.0,2817,'Tranchant, Contondant, Perforant','9','Le plastron est une pièce d''armure supplémentaire accompagnée d’une cuirasse en métal couvre le torse et le dos du cataphracte (le cavalier portant l’armure complète). Elle est souvent composée de plaques de métal superposées ou d''une cotte de mailles renforcée. Le plastron est fait pour protéger l''avant du torse.','Aucun');
INSERT INTO "ARMURES" VALUES (10,'Buste','Cuirasse de fer',15.0,965,'Tranchant, Contondant, Perforant','3','Une cuirasse de fer est une pièce d''armure qui protège le torse du guerrier. Elle est fabriquée en et offre une protection solide contre les attaques lors des combats. La cuirasse de fer se compose généralement de deux parties principales : le plastron frontal qui couvre l''avant du torse et le dosseret qui protège le dos. Ces deux parties sont reliées par des charnières ou des sangles ajustables pour permettre un enfilage et un retrait plus faciles.','Aucun');
INSERT INTO "ARMURES" VALUES (11,'Buste','Robe de cuir',1.0,336,'Contondant','2','Une robe de cuir résistante aux attaques contondantes est une pièce d''armure spécialement conçue pour offrir une protection contre les coups et les impacts provenant d''armes contondantes, telles que des masses, des marteaux ou des bâtons. La robe de cuir est fabriquée à partir de plusieurs couches de cuir épais et solide, cousues ou rivetées ensemble pour former une construction robuste. Le cuir utilisé est généralement de haute qualité, tel que le cuir de buffle, de vachette ou de cheval, qui est connu pour sa résistance et sa durabilité.','Aucun');
INSERT INTO "ARMURES" VALUES (12,'Buste','Cuirasse de bronze',3.0,655,'Tranchant, Contondant, Perforant','1','Une cuirasse de bronze est une pièce d''armure en métal qui protège le torse du guerrier. Elle est fabriquée en utilisant du bronze, un alliage composé principalement de cuivre et d''étain. La cuirasse de bronze se compose généralement de deux parties principales : le plastron frontal qui couvre l''avant du torse et le dosseret qui protège le dos. Ces parties sont souvent reliées par des sangles ou des charnières ajustables pour faciliter l''enfilage et le retrait. Le plastron frontal est conçu pour s''adapter à la forme du torse et offre une protection contre les attaques. Il peut comporter des renforts ou des motifs décoratifs pour renforcer sa solidité et son esthétique.','Aucun');
INSERT INTO "ARMURES" VALUES (13,'Gant','Gants de mailles',0.8,368,'Tranchant, Perforant','1','Les gants de mailles couvrent généralement les doigts, la paume, le dos de la main et une partie de l''avant-bras. Ils offrent une protection efficace contre les coups d''épée, de lance et d''autres armes tranchantes et perforantes. Les mailles articulées permettent une certaine flexibilité et mobilité des doigts, permettant ainsi au combattant de manier ses armes et d''effectuer des gestes précis.','Aucun');
INSERT INTO "ARMURES" VALUES (14,'Gant','Gantelets',1.6,315,'Tranchant, Contondant','1','Les gantelets sont composés de plusieurs parties articulées qui couvrent les doigts, la paume, le dos de la main, les articulations des doigts et les poignets. Ces parties mobiles permettent une certaine flexibilité et une meilleure mobilité des mains tout en fournissant une protection contre les coups d''épée, de hache, de masse et d''autres armes tranchantes.','Aucun');
INSERT INTO "ARMURES" VALUES (15,'Gant','Mitaines',0.6,268,'Rien','0','Les mitaines sont souvent utilisées dans des contextes où une certaine dextérité et une sensibilité tactile sont nécessaires, tout en offrant une protection légère contre les éléments ou les égratignures mineures. Elles peuvent être fabriquées à partir de divers matériaux tels que le coton, la laine, le cuir ou des tissus synthétiques.','1. Équipée en combat, elle donne un bonus de +1% en Dextérité');
INSERT INTO "ARMURES" VALUES (16,'Gant','Mitons',2.0,415,'Tranchant, Contondant, Perforant','2','Les mitons utilisés au Moyen Âge étaient des gants protecteurs qui couvrent la main entière, y compris les doigts, mais sans séparer individuellement les doigts. Les mitons sont généralement fabriqués en métal, tels que l''acier ou le bronze, et sont utilisés pour offrir une protection lors des combats. Les mitons médiévaux sont conçus pour couvrir les doigts dans une seule partie, les empêchant ainsi d''être séparés pour une meilleure dextérité.','Aucun');
INSERT INTO "ARMURES" VALUES (17,'Genouillère','Cuissardes de fer',8.0,528,'Tranchant, Contondant, Perforant','3','Les cuissardes de fer sont des pièces d''armure conçues pour protéger les cuisses du combattant lors des batailles médiévales. Elles sont fabriquées en métal, et offrent une solide protection contre les attaques. Les cuissardes de fer couvrent les cuisses du combattant, de l''aine au genou. Elles sont généralement articulées, permettant ainsi une certaine flexibilité et une bonne mobilité lors des mouvements.','Aucun');
INSERT INTO "ARMURES" VALUES (18,'Genouillère','Pantalon de toile',0.5,5,'Rien','0','Afin de ne pas vous balader tout nu avec vos parties à l’air, merci de vous acheter ce pantalon à prix réduit.','Aucun');
INSERT INTO "ARMURES" VALUES (19,'Genouillère','Cnémide',1.2,317,'Tranchant, Contondant, Perforant','1','Les cnémides couvrent les parties inférieures des jambes, allant des genoux aux chevilles. Elles sont conçues pour envelopper et protéger les tibias et les mollets contre les coups d''épée, de hache et d''autres armes tranchantes. Ces pièces d''armure peuvent être articulées pour permettre une certaine flexibilité et une bonne mobilité lors des mouvements. Elles sont attachées au reste de l''armure, comme les cuissardes, à l''aide de sangles ou de courroies pour assurer un ajustement sécurisé.','Aucun');
INSERT INTO "ARMURES" VALUES (20,'Chaussure','Sandales',0.26,1,'Rien','0','Les sandales sont adaptées aux climats chauds et étaient conçues pour être légères et respirantes, offrant ainsi une certaine ventilation aux pieds. Leur semelle est généralement mince et flexible, permettant une meilleure sensation du sol et une meilleure mobilité. Cependant, elles ne sont pas forcément adaptées pour le combat et peuvent se déchirer si elles prennent un coup.','1. Elles ne sont pas extrêmement solides, et en combat, elles peuvent se déchirer.
1.1. Lancer 1d100 si l’adversaire vise un ou les deux pieds et touche. Entre 91 et 100 (les deux pôles compris) les sandales se déchirent.');
INSERT INTO "ARMURES" VALUES (21,'Chaussure','Chaussures de cuir',1.0,20,'Rien','0','Une chaussure en cuir typique se compose d''une partie supérieure en cuir qui recouvre le dessus du pied, ainsi que d''une semelle en cuir ou en caoutchouc pour offrir une adhérence au sol. La partie supérieure peut être constituée de différentes pièces de cuir assemblées, telles que des quartiers, des empiècements et des languettes, qui sont cousues ou collées ensemble. Les chaussures en cuir peuvent avoir une variété de styles et de formes, allant des chaussures habillées aux chaussures décontractées. Elles peuvent être lacées, à enfiler ou à boucles, selon le design et les préférences personnelles.','Aucun');
INSERT INTO "ARMURES" VALUES (22,'Chaussure','Sabatons',1.2,250,'Tranchant, Perforant','2','Les sabatons sont généralement fabriqués en métal, tels que l''acier ou le bronze, et sont conçus pour recouvrir entièrement le pied, des orteils aux chevilles. Ils offrent une protection solide contre les attaques d''épée, de lance et d''autres armes tranchantes dirigées vers les pieds. Ces pièces d''armure sont souvent articulées, permettant ainsi une certaine flexibilité et une bonne mobilité lors des mouvements. Les sabatons sont fixés au reste de l''armure, comme les jambières, à l''aide de sangles ou de courroies pour assurer un ajustement sécurisé.','Aucun');
INSERT INTO "ARMURES" VALUES (23,'Bouclier','Écu',1.7,240,'Encaisse (Physique)','*','L''écu est fabriqué en bois, souvent renforcé avec du métal ou du cuir, pour lui donner une résistance et une solidité accrues. Il peut être recouvert de tissu, de cuir ou d''un matériau similaire pour une meilleure prise en main. La taille d''un écu peut varier, allant de petits écus utilisés pour la défense individuelle aux grands écus utilisés pour la formation de bouclier lors des batailles en formation. Certains écus comportent également des bords renforcés ou des protubérances en métal, appelées umbo, pour protéger la main ou le poignet du porteur.','1. S’il est équipé en combat, il encaissera 2 dégât de n’importe quel type physique
1.1. Il n’encaisse pas les dégâts magiques.');
INSERT INTO "ARMURES" VALUES (24,'Bouclier','Pavois',11.2,769,'Encaisse (Physique)','*','Le pavois est fabriqué en bois, souvent renforcé avec du métal ou du cuir, pour lui donner une résistance et une solidité accrues. Sa taille est notablement plus grande que celle d''un écu, pouvant mesurer jusqu''à 1,5 à 2 mètres de hauteur. Cela permet de protéger une plus grande partie du corps du combattant, mais l’empêche bien sûr de bouger correctement au vu du poids de le pavois.','1. S’il est équipé en combat, il encaissera 10 dégâts de n’importe quel type physique
1.1. Il n’encaisse pas les dégâts magiques.
2. Le pavois est tellement lourd que s’il est équipé, l’utilisateur voit ses mouvements entravés.
2.1. Déplacement de 1 m
2.2. Cette règle ne s’applique pas aux personnages qui ont l’attribut Force surhumaine ou Force de géant. ');
INSERT INTO "ARMURES" VALUES (25,'Bouclier','Bouclier en amande',2.1,264,'Encaisse (Physique)','*','Le bouclier en amande est généralement fabriqué en bois, bien qu''il puisse également être renforcé avec des matériaux tels que le métal ou le cuir. Il est conçu pour être porté à la main ou attaché au bras du combattant à l''aide de courroies ou de poignées. La forme allongée du bouclier en amande offre une meilleure couverture et une plus grande surface de protection par rapport à d''autres types de boucliers. Il permet de protéger une plus grande partie du corps, notamment le torse et les jambes.','1. S’il est équipé en combat, il encaissera 5 dégâts de n’importe quel type physique
1.1. Il n’encaisse pas les dégâts magiques.');
INSERT INTO "ARMURES" VALUES (26,'Bouclier','Bouclier de bronze',1.9,257,'Encaisse (Physique)','*','Le bouclier de bronze peut varier en taille, en forme et en design en fonction de la culture et de l''époque. Il peut être rond, ovale, rectangulaire ou avoir une autre forme spécifique. Certains modèles peuvent comporter des bords relevés ou des formes décoratives pour renforcer la protection et l''esthétique. Le bronze utilisé dans la fabrication du bouclier offre une bonne résistance et durabilité, ce qui permet une protection efficace contre les attaques d''épées, de lances, de flèches et d''autres armes tranchantes.','1. S’il est équipé en combat, il encaissera 3 dégâts de n’importe quel type physique
1.1. Il n’encaisse pas les dégâts magiques.');
INSERT INTO "ARMURES" VALUES (27,'Bouclier','Pelta',1.4,210,'Encaisse (Physique)','*','La pelta est généralement fabriquée en bois, courbé pour former sa forme caractéristique. Elle peut également être renforcée avec du cuir ou du métal sur la face avant pour augmenter sa résistance aux attaques. La taille de la pelta peut varier, mais elle est souvent de petite à moyenne taille, ce qui permet une maniabilité accrue pour le combattant. Cependant, en raison de sa forme incurvée, la pelta offre une zone de protection relativement limitée par rapport à d''autres types de boucliers.','1. S’il est équipé en combat, il encaissera 1 dégât de n’importe quel type physique
1.1. Il n’encaisse pas les dégâts magiques. ');
INSERT INTO "ARMURES" VALUES (28,'Bouclier','Cape elfique',0.2,3297,'Encaisse (Physique/Magique)','* ','Taillé dans du cuir d’un animal magique, cette cape a des gravures qui accroissent ses effets, ses enchantements lui permettent de résister aussi bien aux coups des attaques physiques que magiques. En plus de ça, elle est extrêmement légère, puisque c’est une cape. Seul bémol, sa rareté et son utilité font qu’il va falloir y mettre le budget pour se la procurer.','1. S’il est équipé en combat, elle encaissera 7 dégâts de n’importe quel type physique
2. S’il est équipé en combat, elle encaissera 4 dégâts des magies suivantes : aquatique, ignis, céleste et terrestre.	');
INSERT INTO "ARMURES" VALUES (29,'Casque','Bonnet de servante',0.1,6,'Rien','0','Le bonnet de servante est un accessoire vestimentaire fonctionnel porté principalement par des servantes et parfois par de jeunes filles. Son objectif principal est de préserver la propreté des cheveux en les protégeant des salissures tout en respectant les normes sociales qui exigeaient de cacher la chevelure des femmes en public. Il se caractérise par sa simplicité et sa modestie, symbolisant ainsi l''humilité, tout en étant utile dans le cadre des tâches ménagères.','Aucun');
INSERT INTO "ARMURES" VALUES (30,'Buste','Robe de servante ',2.0,30,'Rien','0','La robe de servante est une tenue simple et fonctionnelle, composée d''une chemise longue en tissu modeste, d''un corset pour maintenir la silhouette et d''un tablier protecteur porté par-dessus. Conçue pour les tâches domestiques, elle incarne la modestie et la praticité tout en répondant aux besoins du travail.','Aucun');
INSERT INTO "ARMURES" VALUES (31,'Genouillère','Chausse',0.5,12,'Rien','0','Une chausse médiévale est un vêtement pour les jambes et les pieds. Elle est conçue pour être légère et confortable, couvrant les jambes tout en laissant les pieds nus. Les chausses sont généralement fabriquées en tissu et sont attachées séparément à chaque jambe. Elles sont maintenues en place par des attaches ou des jarretelles et sont adaptées à une utilisation quotidienne. ','Aucun');
INSERT INTO "ARMURES" VALUES (32,'Chaussure','Chaussures de servantes',0.65,20,'Rien','0','Les chaussures de servantes sont des souliers simples et fonctionnels. Fabriquées en cuir ou en matériaux similaires, elles sont conçues pour résister à une utilisation quotidienne et aux tâches domestiques. Ces chaussures ont une forme basique, souvent plates ou à talon très bas, offrant confort et durabilité. Bien qu''elles varient en style en fonction de la région et de la période, leur design demeure pratique et adapté aux besoins des servantes, sans fioritures inutiles.','Aucun');
INSERT INTO "OBJETS" VALUES (1,'Torche',0.5,12,'Cet objet fabriqué à partir d’un bâton robuste, d’un tissu rapiécé et de plusieurs tiges de métal pour enrouler et attacher le tissu au bout de bois. Imbibé d’une huile facilement inflammable, la torche est prête à être utilisée et à éclairer les environnements les plus sombres et obscurs. Un indispensable lors de vos explorations !','Normal','Oui','1. Éclaire 9 mètres autour de l’utilisateur
2. La torche se consume au bout d’une heure
2.1. Il est impossible de la rallumer ensuite.');
INSERT INTO "OBJETS" VALUES (2,'Corde',0.4,35,'Fait à la main, à base de chanvre, cette corde robuste à de nombreux usages. Elle est notamment utilisée pour le jardinage ou pour la pêche. Son usage principal reste néanmoins l’escalade, sa longueur permet de descendre en rappel sans craindre de chute mortelle, si toutefois elle est bien attachée à votre bassin.','Normal','Non','1. Permet de descendre ou de monter une paroi si elle est solidement accrochée à quelque chose.
1.1. Sa longueur est de 15 mètres.');
INSERT INTO "OBJETS" VALUES (3,'Outre',1.0,13,'Une outre est un récipient en peau animale, généralement en cuir, conçu pour transporter et stocker des liquides tels que l''eau, le vin ou le lait. Elle est solide et résistante, assurant une conservation efficace des liquides sans fuite. Les outres sont scellées avec un bouchon en bois ou un cordon pour éviter tout déversement. Elles sont couramment utilisées pour le transport des liquides essentiels, tant à la maison qu''à l''extérieur, en offrant une solution pratique pour le stockage et la consommation de boissons.','Normal','Non','1. Peut contenir jusqu''à 3 litres de liquide.');
INSERT INTO "OBJETS" VALUES (4,'Sac de voyage',0.1,29,'Un sac de voyage est un accessoire polyvalent conçu pour faciliter le transport des effets personnels lors de déplacements. Fabriqué à partir de divers matériaux durables, il offre une variété de styles et de tailles pour répondre aux besoins des voyageurs. Les sacs à dos de voyage sont équipés de bretelles rembourrées pour un transport confortable sur les épaules, ainsi que de multiples compartiments et poches pour une organisation efficace. Ils sont conçus pour être pratiques et ergonomiques, offrant une solution de voyage élégante et fonctionnelle pour transporter les essentiels lors de vos déplacements.','Normal','Non','1. Il peut contenir jusqu''à 50 objets
1.1. Les armes et les armures non équipées sont comprises.');
INSERT INTO "OBJETS" VALUES (5,'Tente',15.0,600,'Une tente traditionnelle est une structure portable en toile ou en tissu, conçue pour abriter des personnes en extérieur. Elle se compose généralement d''une armature en bois ou en métal, sur laquelle est tendue une toile solide. Les tentes peuvent varier en taille, de petites tentes individuelles à de grandes tentes de groupe. Elles sont utilisées pour fournir un abri temporaire contre les éléments, que ce soit lors de voyages, de festivals en plein air ou d''autres activités en plein air. Les tentes modernes sont généralement légères, faciles à monter et à démonter, et elles sont souvent équipées de fermetures éclair pour l''entrée et la sortie.','Normal','Non','1. Elle peut abriter jusqu''à cinq personnes.');
INSERT INTO "OBJETS" VALUES (6,'Mouchoir',0.02,1,'Un mouchoir traditionnel est un petit morceau de tissu, généralement en coton ou en lin, conçu pour essuyer le visage ou les mains. Il est de forme carrée ou rectangulaire et peut être plié en plusieurs couches pour une meilleure absorption. Les mouchoirs sont pratiques pour se moucher, s''essuyer la sueur ou nettoyer le visage. Ils sont légers, faciles à transporter et peuvent être lavés et réutilisés','Normal','Oui','Aucun');
INSERT INTO "OBJETS" VALUES (7,'Couverture',0.1,17,'Une couverture d''aventurier est une pièce d''équipement essentielle pour les voyageurs et les aventuriers. Fabriquée à partir de matériaux chauds et isolants tels que la laine, la polaire ou le duvet, elle offre une protection contre le froid et les éléments pendant les expéditions en plein air. Les couvertures d''aventurier sont souvent compactes et légères, ce qui les rend faciles à transporter dans un sac à dos. Elles servent de couche supplémentaire pour dormir sous les étoiles ou dans une tente, offrant chaleur et confort pendant les nuits en plein air. Certaines couvertures d''aventurier sont également conçues pour être polyvalentes, pouvant être utilisées comme tapis de sol, cape ou même comme abri d''urgence. Elles sont un compagnon fiable pour ceux qui explorent les grands espaces et recherchent un refuge contre les rigueurs de la nature.','Normal','Non','Aucun');
INSERT INTO "OBJETS" VALUES (8,'Plante médicinale',1.0,6,'Une plante médicinale est une espèce végétale utilisée pour ses propriétés curatives. Ces plantes renferment des composés naturels aux vertus thérapeutiques. Elles sont préparées sous diverses formes, telles que les infusions ou les décoctions, pour traiter une variété de maux. ','Normal','Oui','1. Soigne 2d8+4 points de vie.');
INSERT INTO "OBJETS" VALUES (9,'Contre-poison',1.5,155,'Il agit en réduisant ou en éliminant les toxines dans le corps, souvent en ralentissant leur absorption ou en accélérant leur élimination. Les contrepoisons sont essentiels dans les situations d''empoisonnement, mais leur efficacité dépend du type de poison ingéré.','Normal','Oui','1. Soigne uniquement les poisons communs.');
INSERT INTO "OBJETS" VALUES (10,'Flèche de bois',0.8,14,'Une flèche en bois est un projectile constitué principalement de bois, avec une pointe également en bois. Elle est conçue pour être utilisée avec un arc pour la chasse ou le tir à l''arc. La partie en bois de la flèche, appelée la tige, est taillée et polie pour assurer une trajectoire droite lorsqu''elle est libérée de l''arc.','Munition','Oui','1. Inflige 4 points de dégâts (perforant)');
INSERT INTO "OBJETS" VALUES (11,'Flèche de fer',1.75,76,'Une flèche en fer avec un corps en bois est un projectile composé d''une tige principalement en bois et d''une pointe en fer. Elle est spécialement conçue pour être utilisée avec un arc pour la chasse ou le tir à l''arc. La partie en bois de la flèche, appelée la tige, est taillée et polie pour assurer une trajectoire stable lorsqu''elle est libérée de l''arc. La pointe en fer est affûtée pour une meilleure pénétration dans la cible.','Munition','Oui','1. Inflige 6 points de dégâts (perforant)');
INSERT INTO "OBJETS" VALUES (12,'Flèche d''argent',1.9,129,'Elle est spécialement conçue pour être utilisée avec un arc dans des situations particulières. La partie en bois de la flèche, connue sous le nom de tige, est méticuleusement façonnée pour assurer une trajectoire précise lors de son décochage. La pointe en argent peut être affûtée pour une meilleure pénétration ou pour des utilisations spécifiques. Les flèches en argent offrent une combinaison unique de la résistance de l''argent avec la légèreté et la flexibilité du bois, en en faisant un choix distinctif pour des applications spéciales ou symboliques.','Munition','Oui','1. Inflige 8 points de dégâts (perforant)');
INSERT INTO "OBJETS" VALUES (13,'Carreau de bois',1.0,64,'Un carreau d''arbalète en bois, la plupart du temps, la point vient se briser dans les os de ses victimes.','Munition','Oui','1. Inflige 5 points de dégâts (perforant)');
INSERT INTO "OBJETS" VALUES (14,'Carreau de fer',2.5,124,'Plus difficile à se procurer qu''un carreau d''arbalète en bois, sa confection assure que l''ennemi subira plus de dégâts perforant avec sa pointe en fer.','Munition','Oui','1. Inflige 9 points de dégâts (perforant)');
INSERT INTO "OBJETS" VALUES (15,'Pierre taillée',0.75,2,'Petite pierre qui sert de projectile pour les frondes.','Munition','Non','1. Inflige 2 points de dégâts (contondant)');
INSERT INTO "OBJETS" VALUES (16,'Minerai de Cardaillite',5.0,5000,'Minerai rare trouvé il y a longtemps dans la prison d''Harmanda par les Cardaillac, ils l''ont nommé par rapport à leur nom de famille. Un seul morceau de ce minerai pèse 5 kilogrammes, il est quasiment impossible d''en transporter un en entier donc, mais on peut faire de précieux équipements avec.','Rare','Non','Aucun');
INSERT INTO "OBJETS" VALUES (17,'Poison élémentaire',0.047,537,'Cette petite fiole contient le poison récupéré d''une créature d''Orbis. Une petite goutte qui rentre dans votre organisme et vous serez assez rapidement empoisonné.','Normal','Oui','1. Peut être utilisé pour empoisonné son arme.
1.1. Le poison partira au bout de 2 heures.');
INSERT INTO "OBJETS" VALUES (18,'Ceinture',0.3,24,'Très pratique pour ceux dont les vêtements ne sont pas ajustés, ça permet de maintenir ses habits sans craindre de les perdre dans une escapade ou un combat.','Normal','Non','Aucun');
