INSERT INTO "MATERIAUX" VALUES (1,'Tissu','Transformé','reel','Tissu simple non rembourré');
INSERT INTO "MATERIAUX" VALUES (2,'Cuir tanné','Transformé','reel','Cuir travaillé et assoupli, utilisé pour armures basiques');
INSERT INTO "MATERIAUX" VALUES (3,'Bois','Transformé','reel','Matériau organique solide, utilisé pour boucliers et armures rudimentaires');
INSERT INTO "MATERIAUX" VALUES (4,'Roche','Transformé','reel','Matière solide, dense et rigide, utilisée pour armures massives ou golems');
INSERT INTO "MATERIAUX" VALUES (6,'Argile','Transformé','réaliste','Matériau friable mais malléable, utilisé pour des golems ou des armures rudimentaires.');
INSERT INTO "MATERIAUX" VALUES (7,'Ossements','Transformé','réaliste','Fragments osseux utilisés comme protection. Cassants mais relativement résistants aux armes de base.');
INSERT INTO "MATERIAUX" VALUES (8,'Cuivre','Métaux','réaliste','Métal rouge malléable, utilisé dans certaines armures primitives. Bon contre le physique mais vulnérable à l’énergie céleste et à la chaleur.');
INSERT INTO "MATERIAUX" VALUES (9,'Fer','Métaux','réaliste','Métal dur et lourd. Offre une bonne protection physique, mais vulnérable à l’eau, à la chaleur et aux énergies célestes.');
INSERT INTO "MATERIAUX" VALUES (10,'Acier','Métaux','réaliste','Alliage de fer et de carbone. Très solide et résistant aux attaques physiques, mais vulnérable à la rouille et aux énergies magiques.');
INSERT INTO "MATERIAUX" VALUES (11,'Argent','Métaux','réaliste','Métal précieux et ductile. Bon tranchant et perforant, faible contre les énergies célestes.');
INSERT INTO "MATERIAUX" VALUES (12,'Or','Métaux','réaliste','Métal précieux, très ductile et malléable. Faible physiquement mais conducteur des énergies.');
INSERT INTO "MATERIAUX" VALUES (14,'Bronze','Métaux','historique','Alliage ancien de cuivre et d étain. Résistant mais moins efficace face aux armes contondantes et aux énergies célestes.');
INSERT INTO "MATERIAUX" VALUES (15,'Rubis','Minerai','fantaisiste','Pierre précieuse rouge, fragile face aux attaques physiques mais très liée au feu et aux énergies mystiques.');
INSERT INTO "MATERIAUX" VALUES (16,'Saphir','Minerai','fantaisiste','Pierre précieuse bleue, fragile physiquement mais étroitement liée à l’eau et aux forces célestes.');
INSERT INTO "MATERIAUX" VALUES (17,'Émeraude','Minerai','fantaisiste','Pierre précieuse verte, fragile physiquement mais fortement liée aux forces célestes et protectrice contre le feu et l’eau.');
INSERT INTO "MATERIAUX" VALUES (18,'Topaze','Minerai','fantaisiste','Pierre précieuse jaune doré, fragile physiquement mais fortement liée aux forces terrestres et aux énergies élémentaires.');
INSERT INTO "MATERIAUX" VALUES (19,'Diamant','Minerai','fantaisiste','Pierre précieuse la plus dure connue, fragilisée face aux attaques physiques mais renforçant de manière équilibrée toutes les affinités élémentaires.');
INSERT INTO "MATERIAUX" VALUES (20,'Mithril','Métaux','fantaisiste','Métal légendaire, plus léger et résistant que l’acier. Offre des bonus équilibrés et universels, adapté à toutes les armes et armures.');
INSERT INTO "MATERIAUX" VALUES (21,'Orichalque','Métaux','fantaisiste','Métal mythique surpassant tous les autres, conférant des bonus colossaux et équilibrés dans tous les domaines.');
INSERT INTO "MATERIAUX" VALUES (22,'Fourrure','Animal','réaliste','Matériau souple et isolant, efficace contre certains éléments mais très vulnérable au feu et aux dégâts physiques.');
INSERT INTO "MATERIAUX" VALUES (24,'Cuirasse épaisse','Animal','réaliste','Cuir épais et travaillé, offrant une protection robuste contre les dégâts physiques.');
INSERT INTO "MATERIAUX" VALUES (26,'Exosquelette d’insecte','Animal','réaliste','Carapace chitineuse résistante des insectes, légère mais vulnérable aux chocs.');
INSERT INTO "MATERIAUX" VALUES (27,'Carapace de tortue','Animal','réaliste','Carapace solide et protectrice, offrant une excellente défense physique et aquatique.');
INSERT INTO "MATERIAUX" VALUES (29,'Carapace de tatou','Animal','réaliste','Carapace segmentée du tatou, flexible mais offrant une bonne défense.');
INSERT INTO "MATERIAUX" VALUES (30,'Carapace de pangolin','Animal','réaliste','Carapace écailleuse du pangolin, robuste et protectrice.');
INSERT INTO "MATERIAUX" VALUES (31,'Écailles de poisson','Animal','réaliste','Écailles protectrices de poisson, excellentes contre l’eau mais vulnérables aux chocs.');
INSERT INTO "MATERIAUX" VALUES (32,'Écailles de lézard','Animal','réaliste','Écailles de lézard : fragiles mais évolutives, offrant une résistance correcte à haut niveau.');
INSERT INTO "MATERIAUX" VALUES (33,'Écailles de serpent','Animal','réaliste','Écailles de serpent, souples et résistantes, mais vulnérables aux attaques perforantes.');
INSERT INTO "MATERIAUX" VALUES (45,'Métal noble','Métaux','reel','Groupe de métaux très stables chimiquement (ex. platine, palladium) : résistances homogènes.');
INSERT INTO "MATERIAUX" VALUES (46,'Peau brute','Animal','reel','Peau animale non traitée : très bonne isolation contre le feu, faible face aux dégâts perforants/physiques.');
INSERT INTO "MATERIAUX" VALUES (47,'Peau huilée ou cirée','Animal','reel','Peau traitée (huilée/cirée) : excellente résistance au feu, légère résistance contondante, vulnérable à l’eau.');
INSERT INTO "MATERIAUX" VALUES (48,'Coquille d’escargot terrestre','Animal','reel','Coquille épaisse d’escargot terrestre : très bonne résistance contondante et au feu, bonus céleste, médiocre en milieu aquatique ; lourde.');
INSERT INTO "MATERIAUX" VALUES (49,'Coquille d’escargots d’eau','Animal','reel','Coquille d’escargots d’eau : très bonne résistance contondante et bonus céleste, faible face au froid/eau, lourde et gênante aux fortes qualités.');
INSERT INTO "MATERIAUX" VALUES (50,'Substance gélatineuse','Animal','fantastique','Masse visqueuse quasi amorphe : énorme résistance aux éléments (feu, eau, céleste, terrestre), mais très vulnérable aux dégâts physiques. Très peu sensible aux états, mais réagit mal aux acides.');
INSERT INTO "MATERIAUX" VALUES (51,'Chair putréfiée','Animal','fantastique','Chair en décomposition : très vulnérable, mais vectrice de maladies et résistances étranges.');
INSERT INTO "MATERIAUX" VALUES (52,'Exosquelette d''insecte','Animal','reel','Carapace chitineuse : très bonne protection contondante/perforante, assez légère aux faibles qualités mais s’alourdit fortement en renforts.');
INSERT INTO "MATERIAUX" VALUES (53,'Carapace de crabe ou de homard','Animal','reel','Carapace chitineuse marine : excellente contre le contondant et l’aquatique, sensible au céleste et aux corrosifs ; lourdit fortement aux hautes qualités.');
INSERT INTO "MATERIAUX" VALUES (54,'Écailles de crocodile ou alligator','Animal','reel','Peau écailleuse très résistante : excellente tenue au feu, solide contre les dégâts physiques, mais lourde et sensible au froid et aux acides.');
INSERT INTO "MATERIAUX" VALUES (55,'Écailles de dragon de feu','Animal','imaginaire','Écailles draconiques infusées de feu : résistance extrême à la chaleur, robustes physiquement, vulnérables au froid et à l’élément aquatique.');
INSERT INTO "MATERIAUX" VALUES (56,'Écailles de dragon de glace','Animal','imaginaire','Écailles draconiques glaciales : résistance extrême au froid et à l’eau, très robustes physiquement, mais vulnérables au feu.');
INSERT INTO "MATERIAUX" VALUES (57,'Écailles de dragon aquatique','Animal','imaginaire','Écailles draconiques adaptées aux grands fonds : énormes résistances à l’eau et à la pression, vulnérabilité relative au céleste.');
INSERT INTO "MATERIAUX" VALUES (58,'Écailles de dragon céleste','Animal','imaginaire','Écailles draconiques infusées d’énergie céleste : résistantes aux forces terrestres et aux chutes, mais vulnérables à l’élément céleste et aux malédictions.');
INSERT INTO "MATERIAUX" VALUES (59,'Écailles de dragon terrestre','Animal','imaginaire','Écailles draconiques gorgées d’énergie tellurique : très résistantes au terrestre, plus vulnérables au céleste ; lourdes mais extrêmement robustes.');
INSERT INTO "MATERIAUX" VALUES (60,'Écailles de seigneur dragon','Animal','imaginaire','Les écailles du seigneur des dragons : elles surpassent toutes les protections connues, équilibrées et redoutables face à tout élément. Elles confèrent une résistance absolue mais pèsent lourd dans la légende.');
INSERT INTO "MATERIAUX" VALUES (61,'Coquille d''escargot terrestre','Animal','reel','Coquille calcaire dure : forte résistance au feu et aux coups contondants, mais lourde et handicapante.');
INSERT INTO "MATERIAUX" VALUES (62,'Coquille d''escargot d''eau','Animal','reel','Coquille calcaire aquatique : très bonne tenue à l’eau et à la pression, bonne face au contondant et au terrestre, mais faible au céleste et à l’acide. Lourde et peu mobile.');
INSERT INTO "MATERIAUX" VALUES (63,'Plumes','Animal','reel','Légères et isolantes : très vulnérables aux dégâts physiques, feu et eau ; bonne résistance au froid et au céleste.');
INSERT INTO "MATERIAUX" VALUES (64,'Pelage','Animal','reel','Pelage isolant : faible protection physique et élémentaire, bon confort thermique, léger et un peu facilitant le déplacement.');
