CREATE VIEW V_MATERIAUX_PAR_QUALITE AS
SELECT
  m.id_materiau,
  m.nom_materiau,
  m.categorie,
  m.realisme,
  m.description,
  q.qualite,
  mc.rarete,
  COALESCE(mv.valeur, mc.base_valeur * q.mult_cout) AS valeur_effective,
  mp.poids AS poids_effectif
FROM MATERIAUX m
JOIN MATERIAUX_COUTS mc ON mc.id_materiau = m.id_materiau
JOIN REF_QUALITE q      ON 1=1
LEFT JOIN MATERIAUX_VALEUR mv
  ON mv.id_materiau = m.id_materiau AND mv.qualite = q.qualite
LEFT JOIN MATERIAUX_POIDS mp
  ON mp.id_materiau = m.id_materiau AND mp.qualite = q.qualite;
CREATE VIEW V_MATERIAUX_PAR_QUALITE_EFFETS AS
SELECT
  m.id_materiau,
  m.nom_materiau,
  me.qualite,
  e.code       AS effet,
  e.categorie  AS effet_categorie,
  e.unite      AS effet_unite,
  me.valeur    AS effet_valeur
FROM MATERIAUX_EFFETS me
JOIN MATERIAUX m  ON m.id_materiau = me.id_materiau
JOIN REF_EFFETS e ON e.id_effet    = me.id_effet;
COMMIT;
